<template>
 <section class="learning-export" aria-label="带出处导出"><div class="export-controls"><label>导出格式<select v-model="format" aria-label="学习资料导出格式" :disabled="busy"><option value="json">JSON 资料档案</option><option value="anki">Anki 导入文本</option></select></label><label v-if="scope==='cards'&&format==='json'"><input type="checkbox" v-model="includeHistory" aria-label="附带全部作答记录" :disabled="busy" /> 附带全部作答记录及调度状态</label><button @click="preview" :disabled="busy||disabled||unsaved">{{ busy?'处理中…':'预览导出当前筛选' }}</button></div>
 <p v-if="unsaved">请先保存或放弃未保存内容，再导出。</p><p v-else-if="format==='json'">{{ scope==='cards'?'保留当前题目与制作时的来源快照，可选择附带完整学习记录。':'保留当前筛选收藏的原文、释义与出处；练习卡和作答记录请在练习卡页导出。' }}JSON 为资料档案，完整恢复请使用数据库备份。</p><p v-else>Anki 首次导入需设置 ID、Front、Back 三字段笔记类型；按正反面卡导入，学习进度和自动拼写核对不迁移。</p>
 <details v-if="format==='anki'" class="anki-export-help"><summary>Anki 导入说明</summary><ol><li>新建含 ID、Front、Back 三字段的笔记类型。</li><li>正面模板使用 <code v-text="'{{Front}}'" />，背面模板使用 <code v-text="'{{FrontSide}}<hr>{{Back}}'" />。</li><li>导入本文件，按字段名映射，Tags 对应标签，启用 HTML；同一笔记类型内使用首字段识别重复。保留 ID，避免不同语境被合并。</li><li>六类练习均为普通正反面卡。请检查导入预览与重复处理选项。</li></ol></details>
 <section v-if="plan" class="export-plan" aria-label="导出范围预览"><h3>当前筛选：{{ plan.count }} {{ scope==='cards'?'张卡片':'条收藏' }} · 约 {{ size(plan.bytes) }}</h3><p v-if="plan.includeHistory">附带 {{ plan.reviewCount }} 次作答及当前调度状态。</p><p v-if="plan.filters.deleted">包含当前回收站筛选中的收藏。</p><p v-if="plan.scope==='cards'&&plan.filters.status!=='active'">卡片状态：{{ {paused:'暂停',archived:'归档',all:'全部'}[plan.filters.status] }}。</p><ul><li v-for="e in plan.sample" :key="e.id">{{ e.title.slice(0,160) }}<small>{{ e.source }}</small></li></ul><p>保存的是本次预览时的已保存快照。之后的修改不自动加入；筛选或格式变化需要重新预览。</p><button class="primary" @click="save" :disabled="busy||disabled||unsaved">选择位置并保存</button><button @click="clear" :disabled="busy">取消本次导出</button></section>
 <p v-if="error" role="alert">{{ error }}</p><p v-if="result" role="status">已导出 {{ result.count }} {{ scope==='cards'?'张卡片':'条收藏' }}<template v-if="result.reviewCount">及 {{ result.reviewCount }} 次作答</template>：<span class="export-path">{{ result.path }}</span></p><p v-if="notice" role="status">{{ notice }}</p>
 </section>
</template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';
const props=defineProps({scope:{type:String,required:true},filters:{type:Object,required:true},disabled:Boolean,unsaved:Boolean}),format=ref('json'),includeHistory=ref(false),plan=ref(null),busy=ref(false),error=ref(''),notice=ref(''),result=ref(null);let version=0,disposed=false;
const clean=value=>JSON.parse(JSON.stringify(value)),size=bytes=>bytes<1024?bytes+' B':bytes<1024*1024?(bytes/1024).toFixed(1)+' KB':(bytes/1024/1024).toFixed(1)+' MB';
function clear(){++version;if(plan.value)window.keeper.learningExportCancel(plan.value.token).catch(()=>{});plan.value=null;error.value='';notice.value='';}
async function preview(){if(busy.value||props.disabled||props.unsaved)return;clear();result.value=null;const seq=version;busy.value=true;try{const r=await window.keeper.learningExportPreview(clean({scope:props.scope,format:format.value,filters:props.filters,includeHistory:props.scope==='cards'&&format.value==='json'&&includeHistory.value}));if(disposed||seq!==version){if(r.ok)await window.keeper.learningExportCancel(r.token);return;}if(!r.ok)throw Error(r.error);plan.value=r;}catch(e){if(!disposed&&seq===version)error.value='预览失败：'+e.message;}finally{if(!disposed)busy.value=false;}}
async function save(){if(busy.value||!plan.value||props.disabled||props.unsaved)return;const seq=version,token=plan.value.token;busy.value=true;error.value='';notice.value='';try{const r=await window.keeper.learningExportSave({token});if(disposed||seq!==version)return;if(r.canceled){notice.value='已取消选择位置，预览仍保留。';return;}if(!r.ok)throw Error(r.error);result.value=r;plan.value=null;await window.keeper.learningExportCancel(token);}catch(e){if(!disposed&&seq===version)error.value='导出未确认，可重试或重新预览：'+e.message;}finally{if(!disposed)busy.value=false;}}
watch(()=>JSON.stringify([props.scope,props.filters,format.value,includeHistory.value]),()=>{clear();result.value=null;});onBeforeUnmount(()=>{disposed=true;clear();});
</script>
<style scoped>.learning-export{padding:14px 0;font-size:12px;line-height:1.8;overflow-wrap:anywhere;width:100%}.export-controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.export-controls select{background:var(--card);color:var(--text);border:1px solid var(--border);border-radius:6px;padding:7px;margin-left:8px}.learning-export p,.learning-export small{color:var(--muted)}.export-plan{margin-top:12px;padding:14px;border:1px solid var(--border);border-radius:8px;background:var(--card)}.export-plan h3{font-size:14px;margin:0}.export-plan button{margin-right:8px}.export-plan small{display:block}.learning-export [role=alert]{color:var(--red)}.export-path{user-select:text;color:var(--text)}.anki-export-help code{white-space:pre-wrap}</style>
